import { FormField, TimePicker } from "@godxjp/ui/data-entry";
import { Button } from "@godxjp/ui/general";
import { useState } from "react";

// Controlled usage inside a React form
export function ShiftStartField() {
  const [startTime, setStartTime] = useState("09:00");

  return (
    <FormField id="shift-start" label="Shift start" controlWidth="9rem">
      <TimePicker
        id="shift-start"
        name="shift_start"
        value={startTime}
        onValueChange={setStartTime}
        minuteStep={15}
      />
    </FormField>
  );
}

// Uncontrolled usage inside a native form
export function CutoffTimeForm() {
  return (
    <form method="post" action="/settings/cutoff">
      <TimePicker
        id="cutoff"
        name="cutoff_time"
        defaultValue="17:00"
        minuteStep={30}
        placeholder="hh:mm"
      />
      <Button type="submit">Save</Button>
    </form>
  );
}
